import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第38章 四分钟","description":"","frontmatter":{},"headers":[],"relativePath":"第38章_四分钟.md","filePath":"第38章_四分钟.md"}'),_={name:"第38章_四分钟.md"};function r(u,p,n,s,q,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第38章-四分钟" tabindex="-1">第38章 四分钟 <a class="header-anchor" href="#第38章-四分钟" aria-label="Permalink to &quot;第38章 四分钟&quot;">​</a></h1><p>四月四号晚上，我的手机响了。</p><p>不是消息，是电话。</p><p>屏幕上是一个陌生号码。我看了一眼，接了。</p><p>第一句话不是她说的。</p><p>是一个男生的声音，很年轻，有点哑，他说：喂？</p><p>我说，喂。</p><p>他说，哦，是你啊。</p><p>然后电话那头有点吵，有人在远处喊了一句什么。他把电话递出去了。</p><p>她接过来。</p><p>她说，是我。</p><p>我说，你在哪。</p><p>她说，我在别人那儿。</p><p>我说，谁的。</p><p>她说，你别问。</p><p>她说，我只有几分钟。</p><p>我说，你说。</p><p>然后她说的事，跟那几分钟不相配。</p><p>她说她家楼下开始装修了，从早上七点敲到晚上六点，她妈还跟人家说好话，因为工人说周末不干了就不来了。</p><p>她说她最近把被子换了，因为她那边回南，被子里都是潮的，摸着像一块凉毛巾。</p><p>她说她妹妹把她一支笔弄丢了，她妈说一支笔有什么。</p><p>她说这些说得很快，一句压一句，中间不给我插话的地方。</p><p>我听她说话。</p><p>这是我第一次听到她用活的嗓子说话，不是在屏幕那头，是这里。</p><p>她的声音比我想的低一点。她说得快的时候尾音会往上飘。她笑的时候会先吸一口气，那口气比她的话还长。</p><p>我说，你别停，你接着说。</p><p>她说，你听得懂？</p><p>我说，我在听。</p><p>她说，行。</p><p>然后她说了一件事，跟前面那些不一样。</p><p>她说，我们班主任今天说了一句话。</p><p>我说，说什么。</p><p>她说，他说，有些同学不要以为家里人不知道。</p><p>我说，然后呢。</p><p>她说，然后全班都没说话。</p><p>我说，你也别说。</p><p>她说，我没说。</p><p>她说，我就是想说，我那天没说。</p><p>那句话说完，她那边有人走过来。她把电话举起来一点，我等了几秒。</p><p>我等的时候听见远处有电视的声音，还有冰箱在响。这些声音凑在一起，是一个别人家的晚上。</p><p>那个人走远了，她把电话接回去，接着刚才那句话说。</p><p>她说，反正就是那些。</p><p>我说，嗯。</p><p>她说，你嗯什么。</p><p>我说，我在听。</p><p>她不说话了。</p><p>那几秒钟里我什么都想说了。我想问她那天有没有出门，我想问她现在在不在家，我想问她以后还上不上线。</p><p>我一句都没问。</p><p>因为她只有四分钟，而这四分钟不是她自己的。</p><p>她忽然说，你那天在河边是不是等了一整天。</p><p>我说，没有。</p><p>她说，你骗人。</p><p>我说，没有。</p><p>她说，好。</p><p>她说，那我没有。</p><p>我们两个人都知道这两句&quot;没有&quot;是什么。</p><p>电话那头又有人喊了一声。</p><p>她说，我要还了。</p><p>我说，好。</p><p>她说，你考试加油。</p><p>我说，好。</p><p>她说，你别老说好。</p><p>她说，你跟我说一句别的。</p><p>我看着天花板，想了三秒。</p><p>我说，你明天能不能自己上线一次。</p><p>她顿了一下。</p><p>她说，我尽量。</p><p>然后电话挂了。</p><p>我把手机拿在手里，听到里头那个&quot;嘟嘟嘟&quot;响了很久。我没有挂。我把它贴在耳朵上，一直听到我自己觉得该挂了为止。</p><p>后来我知道那四分钟是从九点四十七到九点五十一。</p><p>那天晚上我把时间记在本子上。</p><p>我写：四月四号，21点47分至21点51分。四分钟。</p><p>写完我想了想，又补了一行。</p><p>我补的是：她说话的时候先吸一口气。</p><p>第二天她没有上线。</p><p>第三天也没有。</p><p>我把那四分钟在心里过了很多遍。</p><p>过到最后，我记住的不是装修、被子、笔。</p><p>我记住的是她问那句&quot;你那天是不是等了一整天&quot;的时候，声音往下掉了一点。</p><p>她知道。</p><p>她那天一直知道。</p><p>那之后有一个多月，我们没再说过那句话。</p><p>她不提，我不提。</p><p>可从那以后，我在对话框里打字，会先想一下：这句话是不是要自己拦着。</p><p>我不知道她那天在电话里说&quot;反正就是那些&quot;的时候，是不是也在做同一件事。</p><p>第二天我试过回拨。</p><p>我在那个号码上按了三次。</p><p>第一次是空号。</p><p>第二次通了，接的是昨天那个男生。他沉默了一下，说，你别打了。</p><p>我说，我就说一句。</p><p>他说，她不在。</p><p>我说，我知道，我就说一句。</p><p>他说，她不敢接。</p><p>我说，为什么。</p><p>他说，因为接一次就有第二次。</p><p>他把电话挂了。</p><p>我把手机贴在耳朵上，听了很久那个声音。</p><p>后来我去问周奕，我说打电话一分钟多少钱。</p><p>他说，你问这个干什么。</p><p>我说，我算一下。</p><p>他说，两毛多。</p><p>我说，那四分钟。</p><p>他说，那你得省着点花。</p><p>那天我听见这句，心里疼了一下。</p><p>四分钟。</p><p>在她那边，四分钟是有人站在旁边等。</p><p>在我这边，四分钟是两毛多。</p><p>从那以后我把那四分钟背了下来。</p><p>装修，被子，笔。</p><p>三件事，全是小事。</p><p>她只能说小事。</p><p>因为那几分钟里说一句大事，就要用很多次小事换。</p><p>那四分钟里有一件事，我很久以后才想明白。</p><p>她全程没问我一个问题。</p><p>她没说一句&quot;你在干嘛&quot;，没问一句&quot;你想不想我&quot;。</p><p>我那天以为这是因为时间短，没来得及。</p><p>后来我数了一下：她在那四分钟里，讲了五件事。</p><p>装修，被子，笔，班主任那句话，还有那句&quot;你那天是不是等了一整天&quot;。</p><p>前四件是今天发生的事。</p><p>最后一件是两个月前的。</p><p>也就是说，她那四分钟里留了三秒给那天。</p><p>那三秒她是提前想好的。</p><p>她在那几分钟里要先把家里说完，才能把这一句插进去。</p><p>那天晚上我把这件事写在本子上，写完划了。</p><p>因为写下来就像我在拆她。</p><p>但我还是写了。</p><p>我写：她把那天放在最后三秒。</p><p>写完我看着这一行，忽然想起一件事。</p><p>那天晚上她挂了电话之后，我拿手机看时间，看到九点五十一。</p><p>我以为我记错了，又看了一次。</p><p>我为什么记得那么准。</p><p>因为我在那四分钟里一直在看表。</p><p>我怕她那一头的人等急了。</p><p>她那一头等的是人。</p><p>我这一头等的是她自己。</p><p>可那天晚上我没有说。</p><p>我一个字都没提。</p><p>我把它写在了本子上。</p>',138)])])}const l=t(_,[["render",r]]);export{d as __pageData,l as default};
